-- AddDollySettings migration'inin idempotent karsiligi.
-- Veritabani EF migration gecmisi olmadan olusturulduysa (__EFMigrationsHistory bos ve
-- "AuditLogs zaten mevcut" hatasi aliniyorsa) uygulama migration'lari uygulayamaz; bu betik elle calistirilir.
-- Birden fazla kez calistirmak guvenlidir.

ALTER TABLE "Dolly" ADD COLUMN IF NOT EXISTS "PanoNo" text NULL;

CREATE TABLE IF NOT EXISTS "DollySettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DollyId" integer NOT NULL,
    "ConfigVersion" integer NOT NULL,
    "ConfigJson" jsonb NOT NULL,
    "DeviceType" character varying(50) NULL,
    "AppVersion" character varying(50) NULL,
    "AppliedConfigVersion" integer NULL,
    "AppliedAt" timestamp without time zone NULL,
    "LastSeenAt" timestamp without time zone NULL,
    "FetchedConfigVersion" integer NULL,
    "FetchedAt" timestamp without time zone NULL,
    "LastError" character varying(1000) NULL,
    "LastErrorAt" timestamp without time zone NULL,
    "UpdatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_DollySettings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DollySettings_Dolly_DollyId" FOREIGN KEY ("DollyId") REFERENCES "Dolly" ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "DollyConfigEvents" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "DollyId" integer NOT NULL,
    "EventType" character varying(20) NOT NULL,
    "ConfigVersion" integer NULL,
    "Message" character varying(1000) NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_DollyConfigEvents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DollyConfigEvents_Dolly_DollyId" FOREIGN KEY ("DollyId") REFERENCES "Dolly" ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_DollySettings_DollyId" ON "DollySettings" ("DollyId");
CREATE INDEX IF NOT EXISTS "IX_DollyConfigEvents_CreatedAt" ON "DollyConfigEvents" ("CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_DollyConfigEvents_DollyId_CreatedAt" ON "DollyConfigEvents" ("DollyId", "CreatedAt");
